"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9635],{25515:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PerkEffectsDispatcher","desc":"The single writer of the perk buff folders. Every key = permanent layer + shop\\nlayer (Perk Rework part 3). Personal buffs go to\\n`ReplicatedStorage/PerkBuffs/<UserId>`: the player\'s permanent perk values plus\\ntheir live shop perks. Party buffs go to `ReplicatedStorage/PartyPerkBuffs`:\\nthe per-perk MAX permanent level across players (the \\"only highest active\\"\\nrule), plus each shop family\'s strongest live perk counted once, plus\\n`<PerkId>Level`, `<PerkId>HolderId` and `<ShopPerkId>HolderId` (0 = none).\\nRecomputes on allocate/respec (`Signals.OnPerkStateChanged`), run start\\n(`Signals.OnShopPerksChanged`), player join, player leave, and the next shop\\nperk expiry (one `task.delay`, re-armed after every recompute).\\nBridges Scavenger\'s Eye / Lucky Streak and Golden Lure onto\\n`ApplyTierMultiplier`, and Energy Forecast onto `ApplyTypeMultiplier`\\n(`JunkService` listens for both).","realm":["Server"],"source":{"line":20,"path":"src/ServerScriptService/PerkEffectsDispatcher.server.luau"}}')}}]);